-- ========================================================
-- FitLog: Baza ćwiczeń w Supabase (1 ćwiczenie = 1 rekord)
-- Klucz złożony / tablica partii mięśniowych (muscles)
-- ========================================================

-- 1. Tabela ćwiczeń
-- id jest TEXT (slug wbudowanych: b_..., UUID ćwiczeń użytkownika), nie UUID —
-- plany i historia trzymają te same stringi.
CREATE TABLE IF NOT EXISTS public.exercises (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  muscle TEXT NOT NULL,
  muscles TEXT[] NOT NULL DEFAULT '{}',
  created_by UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Istniejąca tabela mogła mieć id UUID — konwersja zachowuje dotychczasowe rekordy użytkownika.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'exercises'
      AND column_name = 'id'
      AND data_type = 'uuid'
  ) THEN
    ALTER TABLE public.exercises ALTER COLUMN id TYPE TEXT USING id::text;
  END IF;
END $$;

ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS muscles TEXT[] NOT NULL DEFAULT '{}';

-- Extra columns for the imported exercises-dataset catalogue (body part, equipment,
-- target muscle, thumbnail/GIF, Polish instructions). NULL for user-made exercises.
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS body_part TEXT;
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS equipment TEXT;
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS target TEXT;
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS secondary_muscles TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS gif_url TEXT;
-- ponytail: only Polish instructions are stored/shown for now (no language switcher
-- in Settings yet). The source dataset also has en/es/it/tr/ru/zh/hi/ko/fr per
-- exercise at https://github.com/hasaneyldrm/exercises-dataset/blob/main/data/exercises.json
-- (record.instructions.<lang>, same "d_"+id id scheme). To add a language switcher
-- later: add instructions_<lang> columns (or one instructions JSONB column) and
-- re-run the generator that produced the INSERT block below with the other language
-- keys instead of just "pl".
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS instructions_pl TEXT;

-- 2. Row Level Security (RLS)
ALTER TABLE public.exercises ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Exercises are viewable by everyone" ON public.exercises;
CREATE POLICY "Exercises are viewable by everyone"
  ON public.exercises FOR SELECT
  USING (true);

DROP POLICY IF EXISTS "Users can insert their own exercises" ON public.exercises;
CREATE POLICY "Users can insert their own exercises"
  ON public.exercises FOR INSERT
  WITH CHECK (auth.uid() = created_by);

DROP POLICY IF EXISTS "Users can update their own exercises" ON public.exercises;
CREATE POLICY "Users can update their own exercises"
  ON public.exercises FOR UPDATE
  USING (auth.uid() = created_by);

DROP POLICY IF EXISTS "Users can delete their own exercises" ON public.exercises;
CREATE POLICY "Users can delete their own exercises"
  ON public.exercises FOR DELETE
  USING (auth.uid() = created_by);

-- 3. Rekordy ćwiczeń (jedno ćwiczenie = jeden rekord ze złożonym zestawem partii mięśniowych)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  muscle = EXCLUDED.muscle,
  muscles = EXCLUDED.muscles;

-- 4. Imported catalogue: https://github.com/hasaneyldrm/exercises-dataset (MIT; data only —
-- thumbnail/GIF media © Gym visual, https://gymvisual.com/, used under that repo's permission
-- at 180×180 resolution; keep the attribution shown wherever the image/GIF is displayed).
-- id = "d_" + the dataset's own 4-digit id, so re-running this generated block is idempotent
-- and never collides with the "b_..." built-ins above or a user's own UUID exercises.
-- Auto-generated from https://github.com/hasaneyldrm/exercises-dataset (MIT, media © Gym visual)
-- 1324 exercises. Run once in the Supabase SQL editor after the ALTER TABLE block above.
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, muscle = EXCLUDED.muscle, muscles = EXCLUDED.muscles,
  body_part = EXCLUDED.body_part, equipment = EXCLUDED.equipment, target = EXCLUDED.target,
  secondary_muscles = EXCLUDED.secondary_muscles, image_url = EXCLUDED.image_url,
  gif_url = EXCLUDED.gif_url, instructions_pl = EXCLUDED.instructions_pl;

